using System.Collections.Generic;
using System.IO;
using System.Text;
using UnityEngine;

namespace Loki.Game
{
    /// <summary>
    /// Item and quest reference tables generated by tools/clientdata/build_tables.py from the client's own
    /// System/iteminfo_new.lub + OngoingQuestInfoList_True.lub (display names, sprite names, descriptions) and
    /// rAthena's item_db / quest_db (English names/titles, item type), shipped in StreamingAssets/data.
    ///
    /// Wave 28 (wtextc): both languages, picked by the language setting (<see cref="ClientText.Portuguese"/>; English only since the design's
    /// 2026-10-15 decision, Lang.EnglishOnly). English: the text pack (Data/TextPack.cs) when it has the row, else the install's
    /// English table (System\english\: items.tsv columns 9-10, quests.tsv 6-8), else rAthena's English name / title; a description
    /// or summary with no English stays EMPTY — the Portuguese text is never shown in its place (counted in the log). Portuguese
    /// (unused while English only): the pack, else the install's root table, else the English. Before wave 28 the item name and
    /// description were always the root table's (Portuguese on the LATAM install) whatever the setting.
    /// </summary>
    public static class GameDb
    {
        public sealed class Item
        {
            public int Id; public string English = "", Resource = "" /* Latin-1 string of CP949 bytes, as GRF paths use */; public int Slots, Type, MinLevel;
            /// <summary>Wave 28: the English and Portuguese name and description as chosen at load (pack, then the player's data).
            /// <see cref="English"/> stays rAthena's English name (logs and smokes compare it).</summary>
            public string NameEn = "", NamePt = "", DescriptionEn = "", DescriptionPt = "";
            /// <summary>The name in the game's language (English: never a Portuguese row; rAthena's name, then "Item #id" when the data has none).</summary>
            public string Name
            {
                get => ClientText.Portuguese && NamePt.Length > 0 ? NamePt : NameEn.Length > 0 ? NameEn : English.Length > 0 ? English : "Item #" + Id;
                set => NameEn = value ?? "";
            }
            public string Description { get => ClientText.Portuguese && DescriptionPt.Length > 0 ? DescriptionPt : DescriptionEn; set => DescriptionEn = value ?? ""; }
            /// <summary>item_db Weight (tenths) and Trade flags: 1 NoDrop 2 NoTrade 4 NoSell 8 NoStorage 16 NoCart 32 NoGuildStorage 64 NoMail 128 NoAuction (itemflags.tsv: id weight trade buy sell buyingstore).</summary>
            public int Weight, TradeFlags;
            /// <summary>item_db Buy / Sell prices (NPC) and whether a buying store may ask for it (Flags.BuyingStore).</summary>
            public int Buy, Sell; public bool BuyingStore;
            public bool NoDrop => (TradeFlags & 1) != 0;
            public bool IsConsumable => Type == 0 || Type == 2 || Type == 11 || Type == 18;
            public string TypeName
            {
                get
                {
                    switch (Type)
                    {
                        // w4lang: shown only (the wrist menu's item details), in the current language; the code compares Type, never this name
                        case 0: return Lang.T("Healing item"); case 2: return Lang.T("Usable item"); case 3: return Lang.T("Etc"); case 4: return Lang.T("Armor"); case 5: return Lang.T("Weapon"); case 6: return Lang.T("Card");
                        case 7: return Lang.T("Pet egg"); case 8: return Lang.T("Pet equipment"); case 10: return Lang.T("Ammunition"); case 11: return Lang.T("Usable item"); case 12: return Lang.T("Shadow equipment"); case 18: return Lang.T("Cash item");
                        default: return Lang.T("Item");
                    }
                }
            }
            /// <summary>The name as lists show it. Wave 28: English shows the name alone (it was the Portuguese name with rAthena's
            /// English in brackets); Portuguese keeps that form (the English name in brackets when it differs).</summary>
            public string Display => !ClientText.Portuguese || string.IsNullOrEmpty(English) || English == Name ? Name : $"{Name} <color=#9aa3b5>({English})</color>";
        }
        public sealed class Quest
        {
            /// <summary><see cref="English"/>: rAthena's quest_db title (logs). Wave 28: the English / Portuguese title, summary and description.</summary>
            public int Id; public string English = "", TitleEn = "", SummaryEn = "", DescriptionEn = "", TitlePt = "", SummaryPt = "", DescriptionPt = "";
            public string Title { get => ClientText.Portuguese && TitlePt.Length > 0 ? TitlePt : TitleEn; set => TitleEn = value ?? ""; }
            public string Summary { get => ClientText.Portuguese && SummaryPt.Length > 0 ? SummaryPt : SummaryEn; set => SummaryEn = value ?? ""; }
            public string Description { get => ClientText.Portuguese && DescriptionPt.Length > 0 ? DescriptionPt : DescriptionEn; set => DescriptionEn = value ?? ""; }
            /// <summary>The title lists show (wave 28: the language's title; English falls back to rAthena's title, then "Quest #id").</summary>
            public string Display => Title.Length > 0 ? Title : English.Length > 0 ? English : "Quest #" + Id;
        }

        private static Dictionary<int, Item> _items;
        private static Dictionary<int, Quest> _quests;

        public static Item GetItem(int id)
        {
            Load();
            if (_items.TryGetValue(id, out var it)) return it;
            return new Item { Id = id, Name = "Item #" + id, English = "", Resource = "", Description = "" };
        }
        /// <summary>Every item of the table (the search store finds items by name).</summary>
        public static IEnumerable<Item> AllItems() { Load(); return _items.Values; }
        /// <summary>Wave 28: every quest of the table (the no-Portuguese check reads them).</summary>
        public static IEnumerable<Quest> AllQuests() { Load(); return _quests.Values; }
        public static Quest GetQuest(int id)
        {
            Load();
            if (_quests.TryGetValue(id, out var q)) return q;
            return new Quest { Id = id, English = "Quest #" + id, Title = "", Summary = "", Description = "" };
        }

        /// <summary>Wave 28: what the load found (smokes and the log): rows, and texts with no English.</summary>
        public static string LoadReport { get; private set; } = "";

        private static string Col(string[] c, int i) => c.Length > i ? c[i] : "";

        private static void Load()
        {
            if (_items != null) return;
            _items = new Dictionary<int, Item>(); _quests = new Dictionary<int, Quest>();
            var latin1 = Encoding.GetEncoding(28591);
            string dir = Path.Combine(Application.streamingAssetsPath, "data");
            try
            {
                foreach (var line in File.ReadLines(Loki.Data.ClientData.File("items.tsv"), Encoding.UTF8))
                {
                    var c = line.Split('\t');
                    if (c.Length < 7 || !int.TryParse(c[0], out int id)) continue;
                    _items[id] = new Item
                    {
                        // columns: id, root (Portuguese) name, rAthena English name, resource, slots, type, root description, min level,
                        // (wave 28) the install's English name and description
                        Id = id, English = c[2], NamePt = c[1], NameEn = Col(c, 8).Length > 0 ? c[8] : c[2], Resource = latin1.GetString(HexToBytes(c[3])),
                        Slots = int.TryParse(c[4], out var s) ? s : 0, Type = int.TryParse(c[5], out var t) ? t : 3,
                        DescriptionPt = c[6].Replace("\\n", "\n"), DescriptionEn = Col(c, 9).Replace("\\n", "\n"),
                        MinLevel = c.Length > 7 && int.TryParse(c[7], out var ml) ? ml : 0
                    };
                }
                string flagsPath = Path.Combine(dir, "itemflags.tsv");
                if (File.Exists(flagsPath))
                    foreach (var line in File.ReadLines(flagsPath, Encoding.UTF8))
                    {
                        var c = line.Split('\t');
                        if (c.Length < 3 || !int.TryParse(c[0], out int id) || !_items.TryGetValue(id, out var it)) continue;
                        it.Weight = int.TryParse(c[1], out var w) ? w : 0; it.TradeFlags = int.TryParse(c[2], out var f) ? f : 0;
                        if (c.Length >= 6) { it.Buy = int.TryParse(c[3], out var bp) ? bp : 0; it.Sell = int.TryParse(c[4], out var sp) ? sp : 0; it.BuyingStore = c[5] == "1"; }
                    }
                foreach (var line in File.ReadLines(Loki.Data.ClientData.File("quests.tsv"), Encoding.UTF8))
                {
                    var c = line.Split('\t');
                    if (c.Length < 5 || !int.TryParse(c[0], out int id)) continue;
                    // columns: id, rAthena English title, root (Portuguese) title, summary, description, (wave 28) the install's English
                    // title, summary, description
                    _quests[id] = new Quest
                    {
                        Id = id, English = c[1], TitlePt = c[2], SummaryPt = c[3], DescriptionPt = c[4].Replace("\\n", "\n"),
                        TitleEn = Col(c, 5).Length > 0 ? c[5] : c[1], SummaryEn = Col(c, 6), DescriptionEn = Col(c, 7).Replace("\\n", "\n"),
                    };
                }
                ApplyPack();
                int noDesc = 0, noSum = 0, noQDesc = 0, noTitle = 0;
                foreach (var it in _items.Values) if (it.DescriptionEn.Length == 0 && it.DescriptionPt.Length > 0) noDesc++;
                foreach (var q in _quests.Values)
                {
                    if (q.TitleEn.Length == 0 && q.TitlePt.Length > 0) noTitle++;
                    if (q.SummaryEn.Length == 0 && q.SummaryPt.Length > 0) noSum++;
                    if (q.DescriptionEn.Length == 0 && q.DescriptionPt.Length > 0) noQDesc++;
                }
                LoadReport = $"{_items.Count} items, {_quests.Count} quests; with Portuguese text and no English (left empty in English): item descriptions {noDesc}, quest titles {noTitle}, summaries {noSum}, descriptions {noQDesc}";
                Debug.Log("[GameDb] " + LoadReport);
            }
            catch (System.Exception e) { Debug.LogError("[GameDb] load failed: " + e.Message); }
        }

        /// <summary>Wave 28: the text pack's items.tsv / quests.tsv rows over the player's tables (a non-empty field wins).</summary>
        private static void ApplyPack()
        {
            var ti = Loki.Data.TextPack.Table("items.tsv");
            if (ti != null)
            {
                int applied = 0, unknown = 0; string first = null;
                foreach (var c in ti.Rows) // id, name_en, name_pt, desc_en, desc_pt
                {
                    if (!int.TryParse(c[0], out int id) || !_items.TryGetValue(id, out var it)) { unknown++; if (first == null) first = c[0]; continue; }
                    it.NameEn = Loki.Data.TextPack.Pick(c[1], it.NameEn); it.NamePt = Loki.Data.TextPack.Pick(c[2], it.NamePt);
                    it.DescriptionEn = Loki.Data.TextPack.Pick(c[3], it.DescriptionEn); it.DescriptionPt = Loki.Data.TextPack.Pick(c[4], it.DescriptionPt);
                    applied++;
                }
                Loki.Data.TextPack.Report(ti, applied, unknown, first);
            }
            var tq = Loki.Data.TextPack.Table("quests.tsv");
            if (tq != null)
            {
                int applied = 0, unknown = 0; string first = null;
                foreach (var c in tq.Rows) // id, title_en, title_pt, summary_en, summary_pt, desc_en, desc_pt
                {
                    if (!int.TryParse(c[0], out int id) || !_quests.TryGetValue(id, out var q)) { unknown++; if (first == null) first = c[0]; continue; }
                    q.TitleEn = Loki.Data.TextPack.Pick(c[1], q.TitleEn); q.TitlePt = Loki.Data.TextPack.Pick(c[2], q.TitlePt);
                    q.SummaryEn = Loki.Data.TextPack.Pick(c[3], q.SummaryEn); q.SummaryPt = Loki.Data.TextPack.Pick(c[4], q.SummaryPt);
                    q.DescriptionEn = Loki.Data.TextPack.Pick(c[5], q.DescriptionEn); q.DescriptionPt = Loki.Data.TextPack.Pick(c[6], q.DescriptionPt);
                    applied++;
                }
                Loki.Data.TextPack.Report(tq, applied, unknown, first);
            }
        }

        private static byte[] HexToBytes(string h)
        {
            var b = new byte[h.Length / 2];
            for (int i = 0; i < b.Length; i++) b[i] = (byte)((Nib(h[2 * i]) << 4) | Nib(h[2 * i + 1]));
            return b;
        }
        private static int Nib(char c) => c <= '9' ? c - '0' : (c | 0x20) - 'a' + 10;
    }
}
